  idx=ls.index(line) # duplicates no
  j=idx+1
  while j<len(ls) and ls[j].startswith('y'):
   mm=re.match(r'y(\d+): (.*)',ls[j]); y=int(mm.group(1))
   for tok in mm.group(2).split():
    xy,val=tok.split('='); 
